draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  // nine
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2, 10, 0, 2 * Math.PI);
  ctx.fill();
  // three
  ctx.beginPath();
  ctx.arc(W/2 - 20, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 20, H/2, 10, 0, 2 * Math.PI);
  ctx.fill();
  // nine
  ctx.beginPath();
  ctx.arc(W/2 + 60, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 60, H/2, 10, 0, 2 * Math.PI);
  ctx.fill();
  // pulsing effect
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.restore();
}
